-- US-90: the shared question bank, six original questions per topic.
-- Rows are matched on content_key (V101), so editing a question here
-- rewrites it in place and practice history stays attached to it.
INSERT INTO questions (topic_id, question_text, category, difficulty, is_system, content_key)
SELECT t.id,
       v.question_text,
       CASE t.category
           WHEN 'dsa' THEN 'dsa'
           WHEN 'system_design' THEN 'system_design'
           WHEN 'behavioural' THEN 'behavioural'
           ELSE 'technical'
       END,
       v.difficulty,
       true,
       v.content_key
FROM (VALUES
    ('api_design-1', 'easy', 'Design the REST endpoints for a to-do app with users and tasks. List the URLs, HTTP methods, and the status codes you would return.'),
    ('api_design-2', 'easy', 'What is the difference between PUT and PATCH? Give an example of when you would use each for updating a user profile.'),
    ('api_design-3', 'medium', 'Your list endpoint returns all 2 million orders at once. Explain how you would add pagination, and compare offset pagination with cursor pagination.'),
    ('api_design-4', 'medium', 'A client retries a payment request after a network timeout and the customer is charged twice. How would you design the API to make this safe? Explain idempotency keys.'),
    ('api_design-5', 'hard', 'You need to change a public API field from a string to an object, and thousands of mobile apps still use the old version. Describe how you would version the API and roll out the change without breaking users.'),
    ('api_design-6', 'hard', 'Design rate limiting for a public API that allows 100 requests per minute per key across 10 servers. Compare token bucket with fixed window, say where the counters live, and explain what happens if the counter store goes down.'),
    ('arrays-1', 'easy', 'Given an array of integers, return the length of the longest run of equal adjacent values. Example: [1,1,2,2,2,3] gives 3. Aim for O(n) time and O(1) extra space.'),
    ('arrays-2', 'easy', 'Move all zeros in an integer array to the end in place, keeping the order of the non-zero values. Example: [0,1,0,3,12] becomes [1,3,12,0,0]. Use one pass and no extra array.'),
    ('arrays-3', 'medium', 'Given an integer array, return a new array where each position holds the product of every other element. Do not use division and run in O(n) time. Example: [1,2,3,4] gives [24,12,8,6].'),
    ('arrays-4', 'medium', 'Rotate an array to the right by k steps in place using O(1) extra space. Example: [1,2,3,4,5,6,7] with k=3 becomes [5,6,7,1,2,3,4]. Note that k can be larger than the array length.'),
    ('arrays-5', 'hard', 'Given an unsorted integer array that may contain negatives and duplicates, return the smallest positive integer that is missing. Use O(n) time and O(1) extra space. Example: [3,4,-1,1] gives 2.'),
    ('arrays-6', 'hard', 'Given an integer array, return the maximum sum of a non-empty contiguous subarray if you may delete at most one element from it. Example: [1,-2,0,3] gives 4, by deleting -2 to get 1,0,3. Aim for O(n) time.'),
    ('backtracking-1', 'easy', 'Given an array of distinct integers, return all subsets. Example: [1,2] gives [], [1], [2], [1,2] in any order.'),
    ('backtracking-2', 'easy', 'Given n, return all binary strings of length n with no two adjacent 1s. Example: n=2 gives 00, 01, 10.'),
    ('backtracking-3', 'medium', 'Given a string that may have repeated letters, return all distinct permutations. Example: aab gives aab, aba, baa.'),
    ('backtracking-4', 'medium', 'Given distinct positive integers and a target, return all combinations that sum to the target, where a number may be reused. Example: [2,3,5], target 8 gives [2,2,2,2], [2,3,3], [3,5].'),
    ('backtracking-5', 'hard', 'Return the number of ways to place n queens on an n by n board so no two attack each other (same row, column or diagonal). Example: n=4 gives 2.'),
    ('backtracking-6', 'hard', 'Given an array of positive integers and k, return true if it can be split into k subsets with equal sums. Example: [4,3,2,3,5,2,1], k=4 gives true (5, 1+4, 2+3, 2+3).'),
    ('behavioural_storytelling-1', 'easy', 'Tell me about a project you are proud of. What was your role, what did you build, and what would you do differently now?'),
    ('behavioural_storytelling-2', 'easy', 'Tell me about a time you had to learn a new tool or language quickly to finish something. How did you go about it and what was the result?'),
    ('behavioural_storytelling-3', 'medium', 'Tell me about a time you had to deliver a project with a requirement that changed late. What did you do and what was the result?'),
    ('behavioural_storytelling-4', 'medium', 'Describe a time you were working on a group project and a teammate was not delivering. What steps did you take, and how did the project end up?'),
    ('behavioural_storytelling-5', 'hard', 'Tell me about a time you made a mistake that affected other people, such as shipping a bug or missing a deadline. How did you find out, what did you do first, and what changed in how you work afterwards?'),
    ('behavioural_storytelling-6', 'hard', 'Tell me about a time you had too much to do and had to drop or delay something. How did you decide what to cut, who did you tell, and would you make the same call again?'),
    ('binary_search-1', 'easy', 'Given an array sorted in ascending order and a target, return the target''s index or -1 if absent, in O(log n) time. Example: [-1,0,3,5,9,12] with target 9 gives 4.'),
    ('binary_search-2', 'easy', 'Return the floor of the square root of a non-negative integer without using a built-in square root function. Example: 8 gives 2. Aim for O(log n) time.'),
    ('binary_search-3', 'medium', 'A sorted array of distinct values was rotated at an unknown point. Return its minimum value in O(log n) time. Example: [4,5,6,7,0,1,2] gives 0.'),
    ('binary_search-4', 'medium', 'Given a sorted array with duplicates and a target, return the first and last index of the target, or [-1,-1] if absent, in O(log n) time. Example: [5,7,7,8,8,10] with target 8 gives [3,4].'),
    ('binary_search-5', 'hard', 'Split an array of positive integers into m contiguous parts so that the largest part sum is as small as possible, and return that sum. Example: [7,2,5,10,8] with m=2 gives 18, from [7,2,5] and [10,8].'),
    ('binary_search-6', 'hard', 'Return the median of two sorted arrays in O(log(min(m,n))) time without merging them. Example: [1,3] and [2] gives 2.0, and [1,2] and [3,4] gives 2.5.'),
    ('binary_search_trees-1', 'easy', 'Given the root of a binary search tree and a value, return the subtree rooted at the node with that value, or null. Example: in 4(2(1,3),7), searching for 2 returns the subtree 2(1,3).'),
    ('binary_search_trees-2', 'easy', 'Given an array sorted in ascending order, build a height-balanced binary search tree from it. Example: [-10,-3,0,5,9] can give root 0 with left child -3 holding -10, and right child 9 holding 5.'),
    ('binary_search_trees-3', 'medium', 'Given a binary tree, return true if it is a valid binary search tree, where every node is greater than all values in its left subtree and less than all in its right. Example: 5(1,4(3,6)) gives false.'),
    ('binary_search_trees-4', 'medium', 'Given the root of a binary search tree and k, return the k-th smallest value, counting from 1. Example: in 3(1(,2),4), k=3 gives 3. Aim for O(h+k) time.'),
    ('binary_search_trees-5', 'hard', 'Delete a given key from a binary search tree and return the new root, keeping it a valid search tree. Handle a node with two children. Example: deleting 3 from 5(3(2,4),6(,7)) can give 5(4(2),6(,7)).'),
    ('binary_search_trees-6', 'hard', 'Two nodes of a binary search tree had their values swapped by mistake. Restore the tree without changing its shape. Example: the tree 3(1,4(2)) has inorder 1,3,2,4, so swapping the values 3 and 2 fixes it.'),
    ('bit_manipulation-1', 'easy', 'Return the number of 1 bits in the binary form of a non-negative integer. Example: 13 (1101) gives 3.'),
    ('bit_manipulation-2', 'easy', 'Return true if an integer n is a power of two, using a single bit expression. Example: 16 gives true; 18 gives false; 0 gives false.'),
    ('bit_manipulation-3', 'medium', 'Every number in an array appears twice except one. Find it in O(n) time and O(1) space. Example: [4,1,2,1,2] gives 4.'),
    ('bit_manipulation-4', 'medium', 'Given n, return an array where entry i is the number of 1 bits in i, for i from 0 to n, in O(n) total. Example: n=5 gives [0,1,1,2,1,2].'),
    ('bit_manipulation-5', 'hard', 'Every number in an array appears twice except two numbers that appear once. Return those two in O(n) time and O(1) extra space. Example: [1,2,1,3,2,5] gives [3,5].'),
    ('bit_manipulation-6', 'hard', 'Return the maximum XOR of any two numbers in an array. Example: [3,10,5,25,2,8] gives 28 (5 XOR 25). Target O(32n).'),
    ('caching_strategies-1', 'easy', 'What is a cache hit ratio, and why does it matter? If a cache read takes 1 ms and a database read takes 50 ms, what is the average read time at a 90 percent hit ratio?'),
    ('caching_strategies-2', 'easy', 'Explain the difference between cache-aside and write-through caching. Give one situation where you would choose each.'),
    ('caching_strategies-3', 'medium', 'A product page is read 50 times for every write. Where would you add a cache, what would you key it on, and how would you keep prices from going stale?'),
    ('caching_strategies-4', 'medium', 'Your cache uses an LRU policy and a nightly report scans millions of rarely used rows, which pushes hot data out. How would you prevent this, and what other eviction policy might fit better?'),
    ('caching_strategies-5', 'hard', 'A very popular cached item expires and 5,000 requests hit the database at the same moment. Explain this problem and give two ways to prevent it.'),
    ('caching_strategies-6', 'hard', 'You cache user profiles in a cache shared by several services, and users complain that profile edits take minutes to show up. Compare TTL expiry, explicit invalidation, and write-through, and describe what can go wrong with each.'),
    ('concurrency_multithreading-1', 'easy', 'Two threads increment a shared counter 1,000 times each and the final value is often below 2,000. Explain why and give two ways to fix it.'),
    ('concurrency_multithreading-2', 'easy', 'What does a mutex do, and why must a thread always release it, even if an exception happens while it holds the lock? Show how you would guarantee this in your language.'),
    ('concurrency_multithreading-3', 'medium', 'Thread A locks resource X then waits for Y, while thread B locks Y then waits for X, and the program hangs. Name this problem, list the four conditions for it, and give a way to prevent it.'),
    ('concurrency_multithreading-4', 'medium', 'You have a producer thread adding jobs to a queue and several consumer threads taking jobs. How would you build this safely, and how do you stop consumers from busy-waiting when the queue is empty?'),
    ('concurrency_multithreading-5', 'hard', 'A cache uses a plain HashMap shared by many request threads, and occasionally a lookup loops forever or returns wrong data. Explain what can go wrong, and compare using a synchronized wrapper, a concurrent map, and per-key locking.'),
    ('concurrency_multithreading-6', 'hard', 'A thread pool has 4 threads. Each task submits a subtask to the same pool and blocks waiting for its result. Under load the system freezes. Explain why, and how you would redesign it.'),
    ('conflict_resolution-1', 'easy', 'Tell me about a time you disagreed with a teammate on how to build something. How did you handle it and what was the outcome?'),
    ('conflict_resolution-2', 'easy', 'Describe a time when someone gave you critical feedback on your work. How did you react, and what did you change?'),
    ('conflict_resolution-3', 'medium', 'Tell me about a time two people on your team wanted different technical approaches and you had to help them reach a decision. What did you do to move things forward?'),
    ('conflict_resolution-4', 'medium', 'Describe a time you had a conflict with someone who was more senior or more experienced than you. How did you raise your view, and what happened?'),
    ('conflict_resolution-5', 'hard', 'Your tech lead picks a design you think will cause problems later, and the team has already agreed. What would you do, and where is the line between pushing back and accepting the decision?'),
    ('conflict_resolution-6', 'hard', 'Tell me about a time you were in a disagreement and later realised you were wrong. How did you find out, how did you handle it with the other person, and what did you learn about the way you argue?'),
    ('database_design-1', 'easy', 'Design a database schema for a library that tracks books, members, and loans. Show the tables, primary keys, and the relationships between them.'),
    ('database_design-2', 'easy', 'What is an index in a relational database? Explain how it speeds up reads and what it costs on writes.'),
    ('database_design-3', 'medium', 'When would you choose a relational database over a document store such as MongoDB for an online store? Explain with the orders and products data.'),
    ('database_design-4', 'medium', 'A query that lists a user''s last 20 orders takes 3 seconds on a table with 100 million rows. Describe how you would find the cause and fix it, including what index you would add.'),
    ('database_design-5', 'hard', 'Your single Postgres database holds 5 TB and write load is growing. Explain how you would shard it, how you would choose the shard key, and what becomes harder after sharding.'),
    ('database_design-6', 'hard', 'A bank transfer must subtract from one account and add to another. Explain how transactions and isolation levels protect against lost updates, and how you would handle it if the two accounts live on different database servers.'),
    ('design_patterns-1', 'easy', 'A configuration object should exist only once in the whole application. Which pattern fits, how would you implement it in Java or Python, and what is one downside of it?'),
    ('design_patterns-2', 'easy', 'You build a notification system that must send by email, SMS or push, chosen at runtime. Which pattern would you use to avoid a big if-else chain, and what would the classes look like?'),
    ('design_patterns-3', 'medium', 'A stock price service must tell a chart, an alert tool and a logger whenever the price changes, without knowing who they are. Name the pattern, sketch the interfaces, and say how subscribers are added and removed.'),
    ('design_patterns-4', 'medium', 'A third-party library returns weather data in a format your app does not use, and you cannot change the library. Which pattern would you apply, and how does it differ from a Decorator?'),
    ('design_patterns-5', 'hard', 'You need to add logging, caching and retry behaviour to a data-fetching class, and combine them in different orders per environment. Why does subclassing get messy here, and how would the Decorator pattern solve it?'),
    ('design_patterns-6', 'hard', 'A service calls a payment provider that is often slow or down, and threads pile up waiting. Explain how a Circuit Breaker works, its three states, and what the caller should do while it is open.'),
    ('distributed_systems-1', 'easy', 'What is the difference between a process crashing and a network partition? Explain why a client cannot always tell them apart.'),
    ('distributed_systems-2', 'easy', 'Explain the CAP theorem in simple words. Give an example of a system that would pick availability and one that would pick consistency.'),
    ('distributed_systems-3', 'medium', 'What is eventual consistency? Describe a feature in a social app, such as like counts, where it is acceptable and one where it is not.'),
    ('distributed_systems-4', 'medium', 'Your service sends a message to a queue after saving to the database, and sometimes the message is lost when the server crashes between the two steps. Explain this problem and how an outbox pattern fixes it.'),
    ('distributed_systems-5', 'hard', 'A queue guarantees at-least-once delivery, so your consumer sometimes sees the same message twice. How would you design the consumer so duplicates do not cause wrong results, such as charging a card twice?'),
    ('distributed_systems-6', 'hard', 'A database with one leader and two followers loses its leader during a write burst. Explain how a new leader is chosen, how you avoid two leaders at once, and what writes might be lost or return stale reads.'),
    ('dp_on_arrays-1', 'easy', 'Given an array of non-negative integers, return the largest sum you can get without picking two neighbors. Example: [2,7,9,3,1] gives 12.'),
    ('dp_on_arrays-2', 'easy', 'Given an array of integers, return the largest sum of a non-empty contiguous subarray in O(n). Example: [3,-4,5,-1,2,-6] gives 6.'),
    ('dp_on_arrays-3', 'medium', 'Return the length of the longest strictly increasing subsequence of an array in O(n log n). Example: [4,1,5,2,6,3,7] gives 4.'),
    ('dp_on_arrays-4', 'medium', 'Return the largest product of a non-empty contiguous subarray. Example: [-2,3,-4,-1,5] gives 60.'),
    ('dp_on_arrays-5', 'hard', 'Return the largest sum of a non-empty subarray after deleting at most one element from it. Example: [1,-2,0,3] gives 4 (delete -2). Target O(n).'),
    ('dp_on_arrays-6', 'hard', 'Return the length of the longest arithmetic subsequence (constant difference) of an array. Example: [9,4,7,2,10] gives 3 (4,7,10); [3,6,9,12] gives 4. Target O(n^2).'),
    ('dp_on_strings-1', 'easy', 'Return the length of the longest common subsequence of two strings. Example: AGGTAB and GXTXAYB gives 4 (GTAB).'),
    ('dp_on_strings-2', 'easy', 'Letters map to numbers (A=1 ... Z=26). Given a string of digits, return the number of ways to decode it. Example: 226 gives 3 (BZ, VF, BBF).'),
    ('dp_on_strings-3', 'medium', 'Return the minimum number of insertions, deletions or replacements needed to turn one string into another. Example: kitten to sitting gives 3.'),
    ('dp_on_strings-4', 'medium', 'Return the length of the longest palindromic subsequence of a string. Example: bbbab gives 4 (bbbb). Target O(n^2).'),
    ('dp_on_strings-5', 'hard', 'Implement matching where ? matches any one character and * matches any sequence (including empty); the whole string must match. Example: s=adceb, p=*a*b gives true; s=acdcb, p=a*c?b gives false.'),
    ('dp_on_strings-6', 'hard', 'Count the distinct subsequences of s that equal t. Example: s=rabbbit, t=rabbit gives 3. Target O(len(s) * len(t)).'),
    ('dp_on_trees-1', 'easy', 'Given a binary tree of integers, return the largest sum along any root-to-leaf path. Example: root 5, left child 4 (with left child 11), right child 8 gives 20.'),
    ('dp_on_trees-2', 'easy', 'Return the diameter of a binary tree: the most edges on any path between two nodes. Example: root 1, children 2 and 3, node 2 has children 4 and 5 gives 3.'),
    ('dp_on_trees-3', 'medium', 'Choose nodes of a binary tree to maximize total value, never choosing a node and its parent together. Example: root 4 with children 1 and 2, and node 1 has a child 5, gives 9 (4+5).'),
    ('dp_on_trees-4', 'medium', 'Return the maximum sum of any path in a binary tree, where a path may start and end at any node. Example: root -3 with children 4 and 5 gives 6 (4, -3, 5).'),
    ('dp_on_trees-5', 'hard', 'Place cameras on nodes of a binary tree; a camera covers its node, parent and children. Return the fewest cameras to cover every node. Example: a path of 4 nodes needs 2; a root with two leaf children needs 1.'),
    ('dp_on_trees-6', 'hard', 'Given a tree with n nodes and its edges, return for each node the sum of distances to all other nodes. Example: n=3, edges [[0,1],[0,2]] gives [2,3,3]. Target O(n).'),
    ('dynamic_programming-1', 'easy', 'You climb n stairs taking 1 or 2 steps at a time. Return the number of distinct ways to reach the top. Example: n=4 gives 5.'),
    ('dynamic_programming-2', 'easy', 'A sequence has a(0)=0, a(1)=1, a(2)=1 and a(n)=a(n-1)+a(n-2)+a(n-3). Return a(n) in O(n) time and O(1) space. Example: n=4 gives 4.'),
    ('dynamic_programming-3', 'medium', 'Given coin values and an amount, return the fewest coins that sum to the amount, or -1. Example: coins [1,5,6], amount 10 gives 2 (5+5); a greedy choice would use 5 coins.'),
    ('dynamic_programming-4', 'medium', 'Given item weights, item values and a capacity, return the best total value when each item is used at most once. Example: weights [1,3,4], values [15,20,30], capacity 4 gives 35.'),
    ('dynamic_programming-5', 'hard', 'Given the dimensions of a chain of matrices, return the fewest scalar multiplications needed to multiply them all. Example: dims [10,20,30,40] (three matrices) gives 18000. Target O(n^3).'),
    ('dynamic_programming-6', 'hard', 'Given a distance matrix between n cities (n up to 15), return the cost of the cheapest tour that starts at city 0, visits every city once and returns. Example: [[0,1,4],[1,0,2],[4,2,0]] gives 7. Target O(2^n * n^2).'),
    ('graph_traversal_bfs_dfs-1', 'easy', 'Given an adjacency list, return the BFS visiting order from node 0, taking neighbors in the listed order. Example: {0:[1,2], 1:[3], 2:[3], 3:[]} gives [0,1,2,3].'),
    ('graph_traversal_bfs_dfs-2', 'easy', 'Given a grid of 0s and 1s, return the size of the largest group of 1s connected up, down, left or right. Example: [[1,1,0],[0,1,0],[0,0,1]] gives 3.'),
    ('graph_traversal_bfs_dfs-3', 'medium', 'In a grid, 0 is empty, 1 is a fresh fruit and 2 is a rotten fruit. Each minute, rotten fruit spoils fresh fruit next to it (4 directions). Return the minutes until none are fresh, or -1 if impossible. Example: [[2,1,0],[1,1,0]] gives 2.'),
    ('graph_traversal_bfs_dfs-4', 'medium', 'Given a start word, an end word and a list of allowed words, return the fewest steps to turn start into end changing one letter per step, each new word coming from the list. Example: cat to dog with [cot,cog,dog] gives 3.'),
    ('graph_traversal_bfs_dfs-5', 'hard', 'Given a 0/1 grid (1 is a wall), move from the top-left to the bottom-right in 4 directions, removing at most k walls. Return the fewest steps, or -1. Example: [[0,1,0],[0,1,0],[0,0,0]] with k=0 gives 4.'),
    ('graph_traversal_bfs_dfs-6', 'hard', 'Given an undirected graph, return the length of its shortest cycle, or -1 if it has none. Example: edges 0-1, 1-2, 2-0, 2-3 gives 3; a tree gives -1. Target O(n*(n+e)).'),
    ('graphs-1', 'easy', 'Given n nodes labeled 0 to n-1 and a list of undirected edges, return the degree of every node. Example: n=3, edges [[0,1],[1,2]] gives [1,2,1]. Target O(n+e).'),
    ('graphs-2', 'easy', 'Given a directed graph as an adjacency list and two nodes s and t, return true if a path leads from s to t. Example: edges 0->1, 1->2: s=0, t=2 gives true; s=2, t=0 gives false.'),
    ('graphs-3', 'medium', 'Given n nodes and a list of undirected edges, return true if the graph is a tree (connected and with no cycle). Example: n=4, edges [[0,1],[1,2],[2,3]] gives true; n=4, edges [[0,1],[2,3]] gives false.'),
    ('graphs-4', 'medium', 'Given an undirected graph, return true if its nodes can be split into two groups so every edge joins nodes from different groups. Example: a 4-node cycle gives true; a triangle gives false. Target O(n+e).'),
    ('graphs-5', 'hard', 'In a directed graph, a node is safe if every path from it ends at a node with no outgoing edges. Return all safe nodes in sorted order. Example: [[1,2],[2],[],[3]] (node i points to the listed nodes) gives [0,1,2].'),
    ('graphs-6', 'hard', 'Find all bridges in an undirected graph, meaning edges whose removal disconnects part of it. Example: edges 0-1, 1-2, 2-0, 1-3 gives [[1,3]]. Target O(n+e).'),
    ('greedy_algorithms-1', 'easy', 'Given a price in cents, return the fewest coins using values 1, 5, 10 and 25. Example: 41 gives 4 (25+10+5+1).'),
    ('greedy_algorithms-2', 'easy', 'Each child has a greed value and each cookie a size; a child is happy if given one cookie of size at least their greed. Return the most happy children. Example: greed [1,2,3], cookies [1,1] gives 1.'),
    ('greedy_algorithms-3', 'medium', 'Each array value is the farthest you may jump from that index. Return true if you can reach the last index starting from index 0. Example: [2,3,1,1,4] gives true; [3,2,1,0,4] gives false. Target O(n).'),
    ('greedy_algorithms-4', 'medium', 'Gas stations sit on a circle; gas[i] is fuel gained at station i and cost[i] is fuel needed to reach the next. Return the start index that completes a lap, or -1. Example: gas [1,2,3,4,5], cost [3,4,5,1,2] gives 3.'),
    ('greedy_algorithms-5', 'hard', 'Rearrange a string so no two adjacent characters are equal, or return an empty string if impossible. Example: aab gives aba; aaab gives an empty string. Target O(n log k).'),
    ('greedy_algorithms-6', 'hard', 'Children stand in a line with ratings. Each gets at least 1 candy, and a child with a higher rating than a neighbor gets more candy than that neighbor. Return the fewest candies in total. Example: [1,0,2] gives 5. Target O(n).'),
    ('hashing-1', 'easy', 'Given an integer array, return the first value whose second occurrence appears earliest while scanning left to right, or -1 if no value repeats. Example: [3,1,4,1,3] gives 1.'),
    ('hashing-2', 'easy', 'Given an unsorted integer array and a target, return the indices of two different elements that add up to the target in O(n) time. Example: [3,2,4] with target 6 gives [1,2].'),
    ('hashing-3', 'medium', 'Given a list of lowercase words, group the words that are anagrams of each other. Example: ["eat","tea","tan","ate","nat","bat"] gives [["eat","tea","ate"],["tan","nat"],["bat"]]. Order of groups does not matter.'),
    ('hashing-4', 'medium', 'Given an integer array, which may contain negatives, and a number k, count the contiguous subarrays whose sum equals k in O(n) time. Example: [1,2,3] with k=3 gives 2, from [1,2] and [3].'),
    ('hashing-5', 'hard', 'Given an unsorted integer array, return the length of the longest run of consecutive integers it contains, in O(n) time and without sorting. Example: [100,4,200,1,3,2] gives 4, for 1,2,3,4.'),
    ('hashing-6', 'hard', 'Design a cache with a fixed capacity that supports get(key) and put(key, value) in O(1) time and evicts the least recently used key when full. Example: capacity 2, put(1,1), put(2,2), get(1) gives 1, put(3,3) evicts key 2, get(2) gives -1.'),
    ('heaps-1', 'easy', 'Return the k-th largest element in an unsorted integer array using a heap of size k, in O(n log k) time. Example: [3,2,1,5,6,4] with k=2 gives 5.'),
    ('heaps-2', 'easy', 'Given an array of stone weights, repeatedly take the two heaviest and smash them: if equal both vanish, otherwise the difference stays. Return the last remaining weight or 0. Example: [2,7,4,1,8,1] gives 1.'),
    ('heaps-3', 'medium', 'Given an integer array and k, return the k most frequent values in any order, in better than O(n log n) time. Example: [1,1,1,2,2,3] with k=2 gives [1,2].'),
    ('heaps-4', 'medium', 'Given a list of 2D points and k, return the k points closest to the origin by Euclidean distance. Example: [[1,3],[-2,2]] with k=1 gives [[-2,2]], since its squared distance 8 is less than 10.'),
    ('heaps-5', 'hard', 'Design a structure with addNum(n) and findMedian() that tracks the median of a stream of integers using two heaps. Example: add 1, add 2, median is 1.5, add 3, median is 2.'),
    ('heaps-6', 'hard', 'Given a list of tasks as letters and a cooldown n, where equal tasks must be at least n slots apart, return the minimum number of time slots to finish all tasks, idling if needed. Example: A,A,A,B,B,B with n=2 gives 8.'),
    ('intervals-1', 'easy', 'Given meeting intervals [start, end], return true if one person can attend all of them. Meetings that only touch at an endpoint are fine. Example: [[0,30],[5,10]] gives false; [[1,2],[2,3]] gives true.'),
    ('intervals-2', 'easy', 'Given a sorted array of distinct integers, return the shortest list of ranges that covers exactly those numbers. Example: [0,1,2,4,5,7] gives [0->2, 4->5, 7].'),
    ('intervals-3', 'medium', 'Merge all overlapping intervals and return the result. Example: [[1,3],[2,6],[8,10]] gives [[1,6],[8,10]]. Target O(n log n).'),
    ('intervals-4', 'medium', 'Given meeting intervals, return the minimum number of rooms needed so no two overlapping meetings share a room. Example: [[0,30],[5,10],[15,20]] gives 2.'),
    ('intervals-5', 'hard', 'Each employee has a sorted list of busy intervals. Return the time gaps when everyone is free, between the earliest start and latest end. Example: [[[1,3],[6,7]],[[2,4]],[[2,5],[9,12]]] gives [[5,6],[7,9]].'),
    ('intervals-6', 'hard', 'Given intervals [l, r] (size is r-l+1) and query points, return for each point the size of the smallest interval containing it, or -1. Example: intervals [[1,4],[2,4],[3,6],[4,4]], queries [2,3,4,5] gives [3,3,1,4].'),
    ('linked_lists-1', 'easy', 'Reverse a singly linked list and return the new head, in O(n) time and O(1) extra space. Example: 1->2->3 becomes 3->2->1.'),
    ('linked_lists-2', 'easy', 'Return the middle node of a singly linked list in one pass, and the second middle if the length is even. Example: 1->2->3->4->5 gives the node 3, and 1->2->3->4 gives the node 3.'),
    ('linked_lists-3', 'medium', 'Given a linked list that may contain a cycle, return the node where the cycle starts, or null if there is none, using O(1) extra space. Example: 1->2->3->4 with 4 pointing back to 2 gives node 2.'),
    ('linked_lists-4', 'medium', 'Remove the n-th node from the end of a singly linked list in a single pass and return the head. Example: 1->2->3->4->5 with n=2 becomes 1->2->3->5.'),
    ('linked_lists-5', 'hard', 'Reverse the nodes of a linked list in groups of k, leaving the final group as is if it has fewer than k nodes. Use O(1) extra space. Example: 1->2->3->4->5 with k=2 becomes 2->1->4->3->5.'),
    ('linked_lists-6', 'hard', 'Merge k sorted linked lists into one sorted list in O(N log k) time, where N is the total number of nodes. Example: 1->4, 1->3 and 2->6 gives 1->1->2->3->4->6.'),
    ('math_number_theory-1', 'easy', 'Return the greatest common divisor of two positive integers in O(log n). Example: 48 and 18 gives 6.'),
    ('math_number_theory-2', 'easy', 'Return how many primes are less than n using a sieve. Example: n=10 gives 4 (2, 3, 5, 7). Target O(n log log n).'),
    ('math_number_theory-3', 'medium', 'Compute x to the power n modulo m in O(log n) time. Example: x=3, n=5, m=7 gives 5 (243 mod 7).'),
    ('math_number_theory-4', 'medium', 'Return the number of trailing zeros in n factorial without computing it. Example: n=25 gives 6. Target O(log n).'),
    ('math_number_theory-5', 'hard', 'Return how many integers from 1 to n share no common factor with n except 1. Example: n=12 gives 4 (1, 5, 7, 11). Target O(sqrt n).'),
    ('math_number_theory-6', 'hard', 'Given a and m, return x in [0, m) with a*x mod m equal to 1, or -1 if none exists. Example: a=3, m=11 gives 4; a=6, m=9 gives -1. Use the extended Euclidean algorithm.'),
    ('matrix_problems-1', 'easy', 'Return the transpose of a matrix with m rows and n columns. Example: [[1,2,3],[4,5,6]] gives [[1,4],[2,5],[3,6]].'),
    ('matrix_problems-2', 'easy', 'Given a square matrix, return the sum of both diagonals, counting the center cell once. Example: [[1,2,3],[4,5,6],[7,8,9]] gives 25.'),
    ('matrix_problems-3', 'medium', 'Return the elements of a matrix in spiral order, starting top-left and going clockwise. Example: [[1,2,3],[4,5,6],[7,8,9]] gives [1,2,3,6,9,8,7,4,5].'),
    ('matrix_problems-4', 'medium', 'Rotate an n by n matrix 90 degrees clockwise in place, with O(1) extra space. Example: [[1,2],[3,4]] becomes [[3,1],[4,2]].'),
    ('matrix_problems-5', 'hard', 'Given a matrix of 0s and 1s, return the area of the largest rectangle containing only 1s. Example: [[1,0,1],[1,1,1]] gives 3. Target O(rows * cols).'),
    ('matrix_problems-6', 'hard', 'Each row and each column of an n by n matrix is sorted ascending. Return the k-th smallest value overall. Example: [[1,5,9],[10,11,13],[12,13,15]], k=8 gives 13.'),
    ('minimum_spanning_tree-1', 'easy', 'Given a connected, weighted, undirected graph, return the total weight of a minimum spanning tree. Example: edges 0-1 (1), 1-2 (2), 0-2 (3) gives 3.'),
    ('minimum_spanning_tree-2', 'easy', 'Given n cities and roads as (a, b, cost), return the lowest total cost to connect all cities, or -1 if impossible. Example: n=3, [[0,1,5],[1,2,3]] gives 8; n=3, [[0,1,5]] gives -1.'),
    ('minimum_spanning_tree-3', 'medium', 'Given points on a plane, connecting two points costs their Manhattan distance. Return the lowest total cost to connect all points. Example: [[0,0],[2,2],[3,10]] gives 13.'),
    ('minimum_spanning_tree-4', 'medium', 'Given a connected weighted graph, return the smallest value M such that using only edges of weight at most M keeps all nodes connected. Example: 0-1 (1), 1-2 (5), 0-2 (3) gives 3.'),
    ('minimum_spanning_tree-5', 'hard', 'For a weighted graph, return the edges that appear in every minimum spanning tree and those that appear in some but not all. Example: a triangle with all weights 1 gives none in every tree and all three in some trees.'),
    ('minimum_spanning_tree-6', 'hard', 'Given the edges of a minimum spanning tree and a new edge (u, v, w), return how much the total MST weight drops after adding it (0 if it does not help). Example: tree 0-1 (4), 1-2 (6), new edge 0-2 (5) gives 1.'),
    ('networking_basics-1', 'easy', 'You type a website address into a browser. Describe in order what happens at the DNS stage before any page data is received, including what a DNS resolver does.'),
    ('networking_basics-2', 'easy', 'What is the difference between an IP address and a port number? Explain how one server can run a web server and an SSH server at the same time on the same IP.'),
    ('networking_basics-3', 'medium', 'Your laptop at home has the address 192.168.1.20 but websites see a different address. Explain what NAT does, and why a friend cannot connect directly to a server you run on your laptop.'),
    ('networking_basics-4', 'medium', 'Two machines are on the same network and one pings the other by IP address successfully, but cannot connect by hostname. List the likely causes and how you would check each one.'),
    ('networking_basics-5', 'hard', 'A video call app and a file download both use your connection. Explain why the call may use UDP while the download uses TCP, and what the app must handle itself when it uses UDP.'),
    ('networking_basics-6', 'hard', 'Users in another continent report your site loads slowly, though the server CPU is idle. Explain how latency and bandwidth differ, what a CDN changes, and which one is the real limit for small pages.'),
    ('oop_principles-1', 'easy', 'A Shape class has a method area(). Circle and Rectangle both extend it. Explain how polymorphism lets you compute the total area of a list of shapes without checking each shape''s type.'),
    ('oop_principles-2', 'easy', 'A BankAccount class has a public field balance that any code can set. What problem does this cause? Show how encapsulation with a private field and a withdraw method fixes it.'),
    ('oop_principles-3', 'medium', 'You have class Bird with fly(), and Penguin extends Bird. Penguin must throw an exception in fly(). Which principle does this break, and how would you redesign the classes?'),
    ('oop_principles-4', 'medium', 'When would you choose composition over inheritance? Use an example of a Car that needs an engine, and explain what goes wrong if Car simply extends Engine.'),
    ('oop_principles-5', 'hard', 'A method in a base class calls an overridable method from its constructor, and the subclass override reads a field that the subclass constructor has not set yet. Explain what happens in Java and how you would avoid it.'),
    ('oop_principles-6', 'hard', 'Your team has an interface PaymentGateway with 12 methods, and one implementation only needs 2 of them. Which principle is being broken, what problems does it cause, and how would you split the interface?'),
    ('operating_systems_basics-1', 'easy', 'What is the difference between a process and a thread? Use a web browser with several tabs as an example of when each might be used.'),
    ('operating_systems_basics-2', 'easy', 'A program allocates memory on the heap in a loop and never frees it, then the machine slows down and the program is killed. Explain the difference between the stack and the heap and what likely happened.'),
    ('operating_systems_basics-3', 'medium', 'Explain what a context switch is, what the OS has to save and restore, and why switching between threads of the same process is cheaper than switching between processes.'),
    ('operating_systems_basics-4', 'medium', 'A machine has 8 GB of RAM but runs programs that need 20 GB in total. Explain how virtual memory and paging make this possible, and what happens when a needed page is not in RAM.'),
    ('operating_systems_basics-5', 'hard', 'A server becomes very slow and the disk is busy, while CPU use is low and free memory is near zero. Explain what thrashing is, how you would confirm it, and what you would do about it.'),
    ('operating_systems_basics-6', 'hard', 'Compare Round Robin and Shortest Job First scheduling. For jobs that need 8, 4 and 2 ms arriving together, calculate the average waiting time for both with a 3 ms quantum, and state the trade-off between them.'),
    ('queues-1', 'easy', 'Implement a queue using only two stacks, with enqueue and dequeue in amortized O(1) time. Example: enqueue 1, enqueue 2, dequeue gives 1, enqueue 3, dequeue gives 2.'),
    ('queues-2', 'easy', 'Implement a circular queue with a fixed capacity, supporting enqueue, dequeue, isEmpty and isFull in O(1) time. Example: with capacity 2, enqueue(1) and enqueue(2) succeed and enqueue(3) returns false.'),
    ('queues-3', 'medium', 'Build a class that takes a window size k and receives numbers one at a time, returning the average of the last k numbers seen using a queue. Example: k=3 and inputs 1,10,3,5 return 1.0, 5.5, 4.67 and 6.0.'),
    ('queues-4', 'medium', 'Given a grid of 0 for open and 1 for blocked cells, return the fewest steps from the top-left to the bottom-right moving in four directions, or -1 if unreachable. Example: [[0,0,0],[1,1,0],[0,0,0]] gives 4.'),
    ('queues-5', 'hard', 'A grid has 0 for empty, 1 for a fresh orange and 2 for a rotten one. Each minute every rotten orange rots its four neighbors. Return the minutes until none are fresh, or -1. Example: [[2,1,1],[1,1,0],[0,1,1]] gives 4.'),
    ('queues-6', 'hard', 'There are n courses and prerequisite pairs [a,b] meaning b must be taken before a. Return a valid order to take all courses, or an empty list if impossible. Example: n=4 with [1,0],[2,0],[3,1],[3,2] gives [0,1,2,3] or [0,2,1,3].'),
    ('recursion-1', 'easy', 'Write a recursive function that returns the sum of the digits of a non-negative integer. Example: 9875 gives 29. Do not convert the number to a string.'),
    ('recursion-2', 'easy', 'Return the n-th Fibonacci number, where F(0)=0 and F(1)=1, first with plain recursion and then with memoization so it runs in O(n). Example: n=6 gives 8.'),
    ('recursion-3', 'medium', 'Given a list of distinct integers, return all of its subsets, including the empty one. Example: [1,2,3] gives [], [1], [2], [3], [1,2], [1,3], [2,3] and [1,2,3] in any order.'),
    ('recursion-4', 'medium', 'Given n, generate all strings of n pairs of parentheses that are correctly balanced. Example: n=2 gives "(())" and "()()". Explain how you prune invalid branches.'),
    ('recursion-5', 'hard', 'Count the ways to place n queens on an n by n chessboard so that no two queens attack each other. Example: n=4 gives 2. Use backtracking with column and diagonal checks.'),
    ('recursion-6', 'hard', 'Given distinct positive integers and a target, return all unique combinations that sum to the target, where each number may be reused any number of times. Example: [2,3,5] with target 8 gives [2,2,2,2], [2,3,3] and [3,5].'),
    ('scalability_load_balancing-1', 'easy', 'Your web server handles 200 requests per second and the team expects 10 times more. Explain the difference between scaling up and scaling out, and which you would try first.'),
    ('scalability_load_balancing-2', 'easy', 'What does a load balancer do? Compare round robin with least connections and say when each one works better.'),
    ('scalability_load_balancing-3', 'medium', 'A web app stores login sessions in server memory, and you want to run five servers behind a load balancer. What problem appears, and what are two ways to fix it?'),
    ('scalability_load_balancing-4', 'medium', 'Your service has a database that becomes the bottleneck at 5,000 reads per second while writes are only 200 per second. Describe the steps you would take to scale it before sharding.'),
    ('scalability_load_balancing-5', 'hard', 'Traffic to your site jumps from 1,000 to 20,000 requests per second within a minute during a sale. Explain how autoscaling and a queue could help, and why autoscaling alone may not be fast enough.'),
    ('scalability_load_balancing-6', 'hard', 'A load balancer health check marks a server as healthy, but users still see errors from it. What could cause this, and how would you design health checks and retries so one bad server does not cause an outage or a retry storm?'),
    ('searching-1', 'easy', 'Given an unsorted integer array, return the second largest distinct value in a single pass, or -1 if there is none. Example: [5,2,9,9,7] gives 7.'),
    ('searching-2', 'easy', 'An array holds n distinct numbers taken from the range 0 to n, so exactly one number is missing. Find it in O(n) time and O(1) extra space. Example: [3,0,1] gives 2.'),
    ('searching-3', 'medium', 'A matrix has each row sorted left to right and each column sorted top to bottom. Return whether a target is in it, in O(rows+cols) time. Example: [[1,4,7],[2,5,8],[3,6,9]] with target 6 gives true.'),
    ('searching-4', 'medium', 'Given an array in which one value appears more than n/2 times, return that value in O(n) time and O(1) extra space. Example: [2,2,1,1,2,2,3] gives 2.'),
    ('searching-5', 'hard', 'Return the k-th smallest element of an unsorted array in expected O(n) time using partitioning, without fully sorting it. Example: [7,10,4,3,20,15] with k=3 gives 7.'),
    ('searching-6', 'hard', 'Given an integer array, return the length of the shortest subarray that, if sorted, makes the whole array sorted. Use O(n) time. Example: [2,6,4,8,10,9,15] gives 5, for [6,4,8,10,9].'),
    ('shortest_path-1', 'easy', 'Given an unweighted undirected graph and nodes s and t, return the fewest edges on a path from s to t, or -1 if none. Example: edges 0-1, 1-2, 0-2 with s=0, t=2 gives 1.'),
    ('shortest_path-2', 'easy', 'Given a directed graph with non-negative edge weights, return the shortest distance from node 0 to every node. Example: 0->1 (4), 0->2 (1), 2->1 (2) gives [0,3,1]. Target O((n+e) log n).'),
    ('shortest_path-3', 'medium', 'A signal starts at node k of a directed graph with edges (u, v, time). Return the time until every node has received it, or -1 if some node never does. Example: n=3, edges [[1,2,1],[2,3,2]], k=1 gives 3.'),
    ('shortest_path-4', 'medium', 'Given flights as (from, to, price), a source, a destination and a limit k of stops in between, return the lowest price, or -1. Example: [[0,1,100],[1,2,100],[0,2,500]], 0 to 2: k=0 gives 500; k=1 gives 200.'),
    ('shortest_path-5', 'hard', 'Given a grid of heights, a route''s effort is the largest height difference between two consecutive cells on it. Return the smallest effort from top-left to bottom-right, moving in 4 directions. Example: [[1,3],[2,4]] gives 2.'),
    ('shortest_path-6', 'hard', 'Given a directed graph with weights that may be negative and a source node, return true if a negative-weight cycle is reachable from it. Example: 0->1 (1), 1->2 (-3), 2->1 (1) with source 0 gives true. Target O(n*e).'),
    ('sliding_window-1', 'easy', 'Given an integer array and a number k, return the largest sum of any k consecutive elements in O(n) time. Example: [2,1,5,1,3,2] with k=3 gives 9, from 5+1+3.'),
    ('sliding_window-2', 'easy', 'Given an integer array, a window size k and a threshold, count the windows of k consecutive elements whose average is at least the threshold. Example: [2,2,2,2,5,5,5,8], k=3, threshold 4 gives 3.'),
    ('sliding_window-3', 'medium', 'Given a string, return the length of the longest substring that has no repeated characters, in O(n) time. Example: "abcabcbb" gives 3, for the substring "abc".'),
    ('sliding_window-4', 'medium', 'Given an array of positive integers and a target, return the length of the shortest contiguous subarray whose sum is at least the target, or 0 if none exists. Example: [2,3,1,2,4,3] with target 7 gives 2.'),
    ('sliding_window-5', 'hard', 'Given strings s and t, return the shortest substring of s that contains every character of t, counting repeats. Return an empty string if there is none. Example: s="ADOBECODEBANC", t="ABC" gives "BANC".'),
    ('sliding_window-6', 'hard', 'Given an integer array and a window size k, return the maximum of every window of k consecutive elements in O(n) time using a deque. Example: [1,3,-1,-3,5,3,6,7] with k=3 gives [3,3,5,5,6,7].'),
    ('sorting-1', 'easy', 'Merge two sorted integer arrays into one sorted array in O(m+n) time. Example: [1,3,5] and [2,4] gives [1,2,3,4,5].'),
    ('sorting-2', 'easy', 'Sort a list of strings by length, shortest first, and break ties alphabetically. Example: ["pear","fig","apple","kiwi"] gives ["fig","kiwi","pear","apple"].'),
    ('sorting-3', 'medium', 'Given a list of intervals as [start,end] pairs, merge all overlapping intervals and return the result. Example: [[1,3],[2,6],[8,10],[15,18]] gives [[1,6],[8,10],[15,18]].'),
    ('sorting-4', 'medium', 'Given a list of non-negative integers, arrange them so that joining them together forms the largest possible number, and return it as a string. Example: [3,30,34,5,9] gives "9534330".'),
    ('sorting-5', 'hard', 'Count the inversions in an integer array, meaning pairs of positions i<j where a[i]>a[j], in O(n log n) time. Example: [2,4,1,3,5] gives 3, from (2,1), (4,1) and (4,3).'),
    ('sorting-6', 'hard', 'Given an integer array, return the largest difference between neighbors in its sorted order, in O(n) time using buckets or radix sort. Return 0 if there are fewer than two elements. Example: [3,6,9,1] gives 3.'),
    ('sql_fundamentals-1', 'easy', 'Table employees(id, name, department, salary). Write a query that lists the name and salary of everyone in the ''Sales'' department earning more than 50000, highest salary first.'),
    ('sql_fundamentals-2', 'easy', 'Table orders(id, customer_id, amount, created_at). Write a query that returns each customer''s total spend in 2025, highest first.'),
    ('sql_fundamentals-3', 'medium', 'Table students(id, name, course_id). Write a query that returns every course_id that has more than 20 students, with the student count. Then explain why you used HAVING instead of WHERE.'),
    ('sql_fundamentals-4', 'medium', 'Table payments(id, user_id, amount, paid_at). Write a query that returns the most recent payment for each user. Name two ways to do it and say which you would pick.'),
    ('sql_fundamentals-5', 'hard', 'A bank transfer runs two updates: subtract 100 from account A and add 100 to account B. The server crashes between them. Explain what can go wrong, how a transaction prevents it, and what the ACID properties guarantee here.'),
    ('sql_fundamentals-6', 'hard', 'Table logins(user_id, login_date) has one row per day a user logged in. Write a query that finds users who logged in on at least 3 consecutive days. Explain how your approach detects a run of days.'),
    ('sql_joins_indexing-1', 'easy', 'Tables customers(id, name) and orders(id, customer_id, amount). What is the difference between an INNER JOIN and a LEFT JOIN here? Which one lists customers who have never placed an order, and how?'),
    ('sql_joins_indexing-2', 'easy', 'Table users(id, email, created_at) has 10 million rows and the query SELECT * FROM users WHERE email = ''a@b.com'' is slow. What would you add to speed it up, and why does it help?'),
    ('sql_joins_indexing-3', 'medium', 'Tables employees(id, name, manager_id) where manager_id points to employees.id. Write a query that returns each employee''s name next to their manager''s name, including employees who have no manager.'),
    ('sql_joins_indexing-4', 'medium', 'You have an index on orders(customer_id, created_at). Which of these queries can use it well: filter by customer_id only, filter by created_at only, filter by both? Explain the leftmost prefix rule.'),
    ('sql_joins_indexing-5', 'hard', 'A query joins orders (50 million rows) to customers (200 thousand rows) and filters orders by status = ''open'', which matches 0.1 percent of rows. EXPLAIN shows a full scan of orders. What would you check and change, and what are the costs of adding the index?'),
    ('sql_joins_indexing-6', 'hard', 'Someone adds an index on every column of a write-heavy events table to make reads faster. Explain why this can hurt, how B-tree indexes affect inserts, and how you would decide which indexes to keep.'),
    ('stacks-1', 'easy', 'Given a string of the characters ()[]{} return true if the brackets are balanced and correctly nested. Example: "{[()]}" gives true and "(]" gives false.'),
    ('stacks-2', 'easy', 'Repeatedly remove pairs of equal adjacent characters from a string until none are left, and return the result. Example: "abbaca" gives "ca", since removing "bb" leaves "aaca" and removing "aa" leaves "ca".'),
    ('stacks-3', 'medium', 'For each element of an integer array, return the next element to its right that is strictly greater, or -1 if there is none. Use O(n) time. Example: [2,1,2,4,3] gives [4,2,4,-1,-1].'),
    ('stacks-4', 'medium', 'Evaluate an arithmetic expression given in reverse Polish notation as an array of tokens, using the operators + - * and integer division. Example: ["2","1","+","3","*"] gives 9.'),
    ('stacks-5', 'hard', 'Given the heights of adjacent bars in a histogram, each of width 1, return the area of the largest rectangle that fits inside it, in O(n) time. Example: [2,1,5,6,2,3] gives 10.'),
    ('stacks-6', 'hard', 'Given a string of only ( and ), return the length of the longest substring that is a valid balanced parentheses sequence. Use O(n) time. Example: ")()())" gives 4.'),
    ('strings-1', 'easy', 'Given a string, return true if it reads the same forwards and backwards after you ignore case and skip every character that is not a letter or digit. Example: "A man, a plan, a canal: Panama" gives true.'),
    ('strings-2', 'easy', 'Reverse the order of the words in a sentence and collapse extra spaces so words are separated by a single space with none at the ends. Example: "  the sky  is blue " gives "blue is sky the".'),
    ('strings-3', 'medium', 'Compress a string by replacing each run of the same character with the character followed by the run length. Return the original if the result is not shorter. Example: "aabcccccaaa" gives "a2b1c5a3".'),
    ('strings-4', 'medium', 'Given a string, return its longest substring that is a palindrome, in O(n^2) time and O(1) extra space. Example: "babad" gives "bab" or "aba". Explain how expanding around each center works.'),
    ('strings-5', 'hard', 'Implement wildcard matching between a text and a pattern, where ? matches any single character and * matches any sequence including an empty one. The whole text must match. Example: text "adceb" and pattern "*a*b" gives true.'),
    ('strings-6', 'hard', 'Multiply two non-negative integers given as decimal strings and return the product as a string. Do not convert the inputs to integers or use a big-number library. Example: "123" times "45" gives "5535".'),
    ('system_design_fundamentals-1', 'easy', 'A team wants to build a simple note-taking app for 10,000 users. Sketch the main components (client, server, database) and explain what each one is responsible for.'),
    ('system_design_fundamentals-2', 'easy', 'What is the difference between latency and throughput? Give an example of a system where you would care more about one than the other.'),
    ('system_design_fundamentals-3', 'medium', 'Design a paste service where users upload text and get a link. Assume 1 million new pastes a day. Estimate storage needs for one year and explain how you would store and serve the content.'),
    ('system_design_fundamentals-4', 'medium', 'Estimate the traffic for a chat app with 5 million daily users, each sending 40 messages a day. How many writes per second is that at average and at peak, and what does that tell you about your design?'),
    ('system_design_fundamentals-5', 'hard', 'Design a notification service that sends email and push messages to 10 million users. Explain how you would handle spikes, retries, and users who get the same notification twice.'),
    ('system_design_fundamentals-6', 'hard', 'You are asked to design a ride-sharing dispatch system for one city with 50,000 active drivers sending location updates every 4 seconds. Discuss how you would store and query locations, and what you would trade off between freshness and cost.'),
    ('tcp_ip_http-1', 'easy', 'Describe the TCP three-way handshake step by step, and say what each side learns from it.'),
    ('tcp_ip_http-2', 'easy', 'A client sends a POST request to create a user and gets back status 201, then another request gets 404 and another gets 500. What does each code tell the client, and who is at fault in each case?'),
    ('tcp_ip_http-3', 'medium', 'Explain the difference between GET and POST and between PUT and PATCH. Which of them are idempotent, and why does idempotency matter when a client retries after a timeout?'),
    ('tcp_ip_http-4', 'medium', 'A packet is lost in the middle of a TCP transfer. Explain how the sender finds out, how it recovers, and how TCP congestion control changes its sending rate afterwards.'),
    ('tcp_ip_http-5', 'hard', 'Your page loads 40 small files and feels slow over HTTP/1.1. Explain head-of-line blocking, how HTTP/2 multiplexing helps, and why HTTP/3 over QUIC still improves things on lossy networks.'),
    ('tcp_ip_http-6', 'hard', 'Walk through what happens during a TLS handshake when a browser opens an https site. Cover the certificate check, how the session key is agreed, and what the certificate authority is trusted for.'),
    ('topological_sort-1', 'easy', 'Given a directed acyclic graph as an adjacency list, return any valid topological order. Example: edges 0->1, 0->2, 1->3, 2->3 gives [0,1,2,3] or [0,2,1,3].'),
    ('topological_sort-2', 'easy', 'Given a directed graph with n nodes, return true if it contains a cycle. Example: edges 0->1, 1->2, 2->0 gives true; edges 0->1, 1->2 gives false.'),
    ('topological_sort-3', 'medium', 'There are n tasks and pairs [a, b] meaning task b must come before task a. Return an order that finishes all tasks, or an empty list if impossible. Example: n=2, [[1,0]] gives [0,1]; [[1,0],[0,1]] gives [].'),
    ('topological_sort-4', 'medium', 'Words are sorted by the rules of an unknown alphabet. Return one valid order of the letters used. Example: [ba, bc, ac, cab] gives bac.'),
    ('topological_sort-5', 'hard', 'Given a DAG with nodes 0 to n-1, return the topological order that is smallest when compared element by element. Example: n=4, edges [[2,0],[3,1]] gives [2,0,3,1]. Target O((n+e) log n).'),
    ('topological_sort-6', 'hard', 'Tasks have durations and prerequisite edges, and any number can run in parallel. Return the earliest time everything can finish. Example: durations [3,2,4], edges 0->2 and 1->2 gives 7.'),
    ('trees-1', 'easy', 'Given the root of a binary tree, return its maximum depth, counted in nodes on the longest root-to-leaf path. Example: root 3 with children 9 and 20, where 20 has children 15 and 7, gives 3.'),
    ('trees-2', 'easy', 'Given the root of a binary tree, return true if it is a mirror image of itself around its center. Example: root 1 with children 2 and 2, whose children are 3,4 on the left and 4,3 on the right, gives true.'),
    ('trees-3', 'medium', 'Given the root of a binary tree, return its values level by level from left to right as a list of lists. Example: root 3 with children 9 and 20, where 20 has children 15 and 7, gives [[3],[9,20],[15,7]].'),
    ('trees-4', 'medium', 'Given the root of a binary tree that is not a search tree and two nodes in it, return their lowest common ancestor. Example: in the tree 3(5(6,2),1(0,8)), nodes 5 and 1 give 3, and nodes 6 and 2 give 5.'),
    ('trees-5', 'hard', 'Given a binary tree of integers, return the maximum sum over any path that follows parent-child links, which may start and end at any node. Example: -10 with children 9 and 20, where 20 has children 15 and 7, gives 42.'),
    ('trees-6', 'hard', 'Design functions to serialize a binary tree to a string and deserialize that string back into the same tree. Example: the tree 1(2,3(4,5)) must round trip to an identical tree, including its null children.'),
    ('tries-1', 'easy', 'Implement a trie that supports insert(word), search(word) for a full word, and startsWith(prefix). Example: after insert("apple"), search("app") is false and startsWith("app") is true.'),
    ('tries-2', 'easy', 'Given a list of words and a prefix, count how many words start with that prefix using a trie. Example: ["apple","app","apt","bat"] with prefix "ap" gives 3.'),
    ('tries-3', 'medium', 'Given an array of strings, return their longest common prefix by building a trie and walking down while there is a single child. Example: ["flower","flow","flight"] gives "fl".'),
    ('tries-4', 'medium', 'Given a list of words and a prefix, return up to three words that start with the prefix, in alphabetical order, using a trie. Example: ["car","card","care","cat","dog"] with prefix "car" gives ["car","card","care"].'),
    ('tries-5', 'hard', 'Design a word dictionary with addWord(word) and search(word), where search may use . to match any single letter. Example: after adding "bad" and "dad", search("b.d") is true and search("..z") is false.'),
    ('tries-6', 'hard', 'Given a grid of letters and a list of words, return every word that can be formed by a path of horizontally or vertically adjacent cells, using no cell twice in a word. Use a trie. Example: board [["o","a"],["e","t"]] with words oat, eat, oath gives ["oat"].'),
    ('two_pointers-1', 'easy', 'Given an array sorted in ascending order and a target, return the 1-based indices of two numbers that add up to the target, using O(1) extra space. Example: [2,7,11,15] with target 9 gives [1,2].'),
    ('two_pointers-2', 'easy', 'Remove duplicates from a sorted array in place and return the number of unique values. The first part of the array must hold the unique values in order. Example: [1,1,2,2,3] returns 3 and starts with 1,2,3.'),
    ('two_pointers-3', 'medium', 'Given an array of wall heights, pick two walls to maximize distance between them times the height of the shorter one. Return that value in O(n) time. Example: [3,9,4,8] gives 16, from the walls 9 and 8.'),
    ('two_pointers-4', 'medium', 'Sort an array containing only 0, 1 and 2 in place in a single pass without using a library sort. Example: [2,0,2,1,1,0] becomes [0,0,1,1,2,2].'),
    ('two_pointers-5', 'hard', 'Given an array of non-negative bar heights, compute how many units of rain water are trapped between the bars. Use O(n) time and O(1) extra space. Example: [3,0,2,0,4] gives 7.'),
    ('two_pointers-6', 'hard', 'Given an integer array and a target, return all unique sets of four values that add up to the target, with no duplicate sets. Example: [1,0,-1,0,-2,2] with target 0 gives [-2,-1,1,2], [-2,0,0,2] and [-1,0,0,1].'),
    ('union_find-1', 'easy', 'Given n nodes and a list of pairs that are connected, return the number of connected groups. Example: n=5, pairs [[0,1],[1,2],[3,4]] gives 2.'),
    ('union_find-2', 'easy', 'Given friendship pairs and two people a and b, return true if they are in the same friend circle (friends of friends count). Example: pairs [[0,1],[1,2]]: 0 and 2 gives true; 0 and 3 gives false.'),
    ('union_find-3', 'medium', 'Edges of a graph are added one at a time. Return the first edge that connects two nodes already connected, or an empty list if none. Example: [[1,2],[2,3],[1,3]] gives [1,3].'),
    ('union_find-4', 'medium', 'Each account is a name followed by emails. Merge accounts that share any email, keeping emails sorted. Example: [[A,a@x,b@x],[A,b@x,c@x],[B,d@x]] gives [[A,a@x,b@x,c@x],[B,d@x]].'),
    ('union_find-5', 'hard', 'Given weighted edges and queries (u, v, limit), answer each query true if u reaches v using only edges with weight below limit. Example: edges [[0,1,2],[1,2,4]]: query (0,2,5) is true; (0,2,4) is false. Target O((e+q) log(e+q)).'),
    ('union_find-6', 'hard', 'A grid starts as all water. Land cells are added one at a time. After each addition, return the number of islands (4-direction). Example: 2x2 grid, positions [[0,0],[1,1],[0,1]] gives [1,2,1].')
) AS v (content_key, difficulty, question_text)
JOIN topics t ON t.slug = split_part(v.content_key, '-', 1)
ON CONFLICT (content_key) DO UPDATE
SET question_text = EXCLUDED.question_text,
    difficulty = EXCLUDED.difficulty,
    category = EXCLUDED.category,
    updated_at = now()
WHERE questions.question_text IS DISTINCT FROM EXCLUDED.question_text
   OR questions.difficulty IS DISTINCT FROM EXCLUDED.difficulty
   OR questions.category IS DISTINCT FROM EXCLUDED.category;
